def count_zeros(n):
    return str(n).count('0')

def solve():
    # M is 1000 ones
    M = int('1' * 1000)
    max_A = 0
    best_k = 0
    for k in range(1, 1001):
        N = int('1' * k)
        Q = M // N
        A = count_zeros(Q)
        if A > max_A:
            max_A = A
            best_k = k
    return max_A, best_k

print(solve())

